function IdolLive3D_PosLockedCameraMotion:__init( idolLive3D_Camera_, baseJson_, vcam_ )

    self.idolLive3D_Camera = idolLive3D_Camera_
    self.baseJson = baseJson_

    self.vcam = vcam_
    self.vcamTF = vcam_.transform

    self.pos = Vector3.zero
    self.lookDir = Vector3.forward

    self.yaw = 
    {
        min = -30,
        max =  30,
        raw_v = 0,      --[min,max]
        smooth_v = 0,   --[min,max]
    }

    self.pitch = 
    {
        min = -20,
        max =  20,
        raw_v = 0,      --[min,max]
        smooth_v = 0,   --[min,max]
    }

    self.zoom = 
    {
        minDistanceOffset = -0.1,   -- 临时值
        maxDistanceOffset = 0.1,    -- 临时值
        minFov = 20,    -- 临时值
        maxFov = 35,    -- 临时值
        ---
        raw_t = 0,      --[0,1]
        smooth_t = 0,   --[0,1]
        init_t = 0.5,
    }
    ---
    self.isInit = true
end





-- 需手动调用 Delete()
function IdolLive3D_PosLockedCameraMotion:__delete()
    
end




-- ===============================================================

function IdolLive3D_PosLockedCameraMotion:SelfUpdate()
    if self.isInit ~= true then 
        return
    end 

    self.yaw.smooth_v   = Mathf.Lerp( self.yaw.smooth_v,    self.yaw.raw_v,     0.15 )
    self.pitch.smooth_v = Mathf.Lerp( self.pitch.smooth_v,  self.pitch.raw_v,   0.15 )
    self.zoom.smooth_t  = Mathf.Lerp( self.zoom.smooth_t,   self.zoom.raw_t,    0.15 )

    ---
    self.vcamTF.position = self.pos
    self.vcamTF:LookAt( self.vcamTF.position + self.lookDir, Vector3.up )

    self.vcamTF:Rotate( Vector3(self.pitch.smooth_v, self.yaw.smooth_v, 0), Space.Self )
    self.vcamTF:LookAt(self.vcamTF.position+self.vcamTF.forward, Vector3.up)
    ----
    local zoomLen = KTool.Remap( 0, 1, self.zoom.minDistanceOffset, self.zoom.maxDistanceOffset, self.zoom.smooth_t )
    self.vcamTF.position = self.vcamTF.position - self.vcamTF.forward * zoomLen
    ---
    local fov = KTool.Remap( 0, 1, self.zoom.minFov, self.zoom.maxFov, self.zoom.smooth_t )
    local lens = self.vcam.m_Lens 
    lens.FieldOfView = fov
    self.vcam.m_Lens = lens
end



----------------------------------------------------------


function IdolLive3D_PosLockedCameraMotion:SetActive( isActive_ )
    KTool.SetActive( self.vcamTF.gameObject, isActive_ == true )
end 



function IdolLive3D_PosLockedCameraMotion:SetPriority( priority_ )
    self.vcam.Priority = checkNumber(priority_)
end




---@param params_ table
function IdolLive3D_PosLockedCameraMotion:SetRangeParams( params_ )

    self.yaw.min = checkNumber(params_.yaw.min)
    self.yaw.max = checkNumber(params_.yaw.max)

    self.pitch.min = checkNumber(params_.pitch.min)
    self.pitch.max = checkNumber(params_.pitch.max)

    self.zoom.minDistanceOffset = checkNumber(params_.zoom.minDistanceOffset)
    self.zoom.maxDistanceOffset = checkNumber(params_.zoom.maxDistanceOffset)
    self.zoom.minFov = checkNumber(params_.zoom.minFov)
    self.zoom.maxFov = checkNumber(params_.zoom.maxFov)

end


----------------------------------------------------------


function IdolLive3D_PosLockedCameraMotion:ResetAllImmediately()
    self:ResetImmediately() -- 重置参数
    self:SelfUpdate()   -- 直接改写 vcam
end



-- 重置 yaw, pitch, zoom 值
function IdolLive3D_PosLockedCameraMotion:ResetImmediately()
    self.yaw.raw_v = 0
    self.yaw.smooth_v = 0
    ---
    self.pitch.raw_v = 0
    self.pitch.smooth_v = 0
    ---
    self.zoom.raw_t = self.zoom.init_t
    self.zoom.smooth_t = self.zoom.raw_t
end



function IdolLive3D_PosLockedCameraMotion:SetImmediately( params_ )
    self.pos = params_.vcamPos
    self.lookDir = Vector3( params_.vcamDir.x, params_.vcamDir.y, params_.vcamDir.z ).normalized -- 防止是 json 里的 table 数据...
    self.zoom.init_t = params_.zoom.init_t
    
    ---
    self:ResetImmediately()
end



