-- 触发: 偏航 (旋转观察 idol )
function IdolLive3D_PosLockedCameraMotion:YawByDelta( rotateDelta_ )


    local threshold = 8  -- todo: 速度上界, 33, 未来走配表
    rotateDelta_ = rotateDelta_ * 0.6
    
    -- 反二项曲线, 让响应变快:
    local w = Mathf.Clamp01( KTool.Remap( 0, threshold, 0, 1, Mathf.Abs(rotateDelta_) ))
    --w = 1 - (1-w)*(1-w)
    local rotateDelta = w * threshold * (rotateDelta_<=0 and -1 or 1)
    ---
    self.yaw.raw_v = Mathf.Clamp( self.yaw.raw_v + rotateDelta, self.yaw.min, self.yaw.max )
end



-- 触发: 俯仰
function IdolLive3D_PosLockedCameraMotion:PitchByDelta( rotateDelta_ )

    local threshold = 8  -- todo: 速度上界, 33, 未来走配表
    rotateDelta_ = rotateDelta_ * 0.6
        
    -- 反二项曲线, 让响应变快:
    local w = Mathf.Clamp01( KTool.Remap( 0, threshold, 0, 1, Mathf.Abs(rotateDelta_) ))
    --w = 1 - (1-w)*(1-w)
    local rotateDelta = w * threshold * (rotateDelta_<=0 and -1 or 1)
    ---
    self.pitch.raw_v = Mathf.Clamp( self.pitch.raw_v + rotateDelta, self.pitch.min, self.pitch.max )
end




-- 触发: 镜头缩放
function IdolLive3D_PosLockedCameraMotion:ZoomByDelta( deltaPinch_ )

    local pinchVal = deltaPinch_
    if IdolLive3D_States.isWindowsPlatform == true then 
        pinchVal = pinchVal * 0.015
    else    
        pinchVal = pinchVal * 0.015 * 0.2
    end 

    self.zoom.raw_t = Mathf.Clamp01( self.zoom.raw_t + pinchVal )
end








return IdolLive3D_PosLockedCameraMotion
